// Converta a string com JSON.parse e crie um <li> para cada item.

solution.js:
const dados = '[{"titulo":"HTML"},{"titulo":"CSS"},{"titulo":"JavaScript"}]';
const lista = document.querySelector('#lista');

for (const item of JSON.parse(dados)) {
  const li = document.createElement('li');
  li.textContent = item.titulo;
  lista.appendChild(li);
}

starter.js:
const lista = document.querySelector('#produtos');
const url = 'https://api.exemplo.com/produtos';

// Busque os produtos com fetch e crie um <li> para cada nome.

solution.js:
const lista = document.querySelector('#produtos');
const url = 'https://api.exemplo.com/produtos';

fetch(url)
  .then((resposta) => resposta.json())
  .then((produtos) => {
    for (const produto of produtos) {
      const li = document.createElement('li');
      li.textContent = produto.nome;
      lista.appendChild(li);
    }
  });

