starter.js:
const lista = document.querySelector('#destaques');
const url = 'http://localhost:3000/noticias';

// Busque as notícias, filtre as com 100 curtidas ou mais e mostre os títulos.

solution.js:
const lista = document.querySelector('#destaques');
const url = 'http://localhost:3000/noticias';

fetch(url)
  .then((resposta) => resposta.json())
  .then((dados) => {
    const destaques = dados.noticias.filter((noticia) => noticia.curtidas >= 100);
    for (const noticia of destaques) {
      const li = document.createElement('li');
      li.textContent = noticia.titulo;
      lista.appendChild(li);
    }
  });
